1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	
7	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
8	const MS_PER_AVG_MONTH = 30.44 * 86400_000;
9	
10	/**
11	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
12	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
13	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
14	 * and respects the "one in-flight job per server" invariant.
15	 */
16	
17	/** Allowed scheduled-backup cadences (hours). Kept small + human-friendly. */
18	export const BACKUP_INTERVAL_CHOICES = [12, 24, 48, 72, 168] as const;
19	
20	async function ownedServer(serverId: string) {
21	  const user = await requireUser();
22	  const server = await db.server.findUnique({
23	    where: { id: serverId },
24	    include: { plan: true, osTemplate: true },
25	  });
26	  if (!server) throw new Error("Not found");
27	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
28	  return { user, server };
29	}
30	
31	async function hasInflightJob(serverId: string): Promise<boolean> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  return pending > 0;
36	}
37	
38	// ---------- 1. Scheduled backups ----------
39	
40	/**
41	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
42	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
43	 * first backup on its next pass.
44	 */
45	export async function setBackupSchedule(
46	  serverId: string,
47	  enabled: boolean,
48	  intervalHours: number
49	): Promise<{ error?: string }> {
50	  const { user, server } = await ownedServer(serverId);
51	
52	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
53	    return { error: "Choose a valid backup interval." };
54	  }
55	
56	  await db.server.update({
57	    where: { id: server.id },
58	    data: {
59	      autoBackup: enabled,
60	      backupIntervalHours: enabled ? intervalHours : null,
61	    },
62	  });
63	  await db.auditLog.create({
64	    data: {
65	      userId: user.id,
66	      action: "server.backup_schedule",
67	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
68	    },
69	  });
70	  revalidatePath(`/dashboard/servers/${serverId}`);
71	  return {};
72	}
73	
74	// ---------- 2. Reinstall to a different OS ----------
75	
76	/**
77	 * Switch the server to a different OS image and reinstall. This ERASES all data:
78	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
79	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
80	 */
81	export async function reinstallToOs(
82	  serverId: string,
83	  osTemplateId: string
84	): Promise<{ error?: string }> {
85	  const { user, server } = await ownedServer(serverId);
86	
87	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
88	    return { error: "Server must be running or stopped to reinstall." };
89	  }
90	
91	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
92	  if (!os?.active) return { error: "That operating system isn't available." };
93	  if (os.id === server.osTemplateId) {
94	    return { error: "This server is already running that operating system." };
95	  }
96	  if (server.plan.ramMB < os.minRamMB) {
97	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
98	  }
99	  if (server.plan.diskGB < os.minDiskGB) {
100	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
101	  }
102	
103	  if (await hasInflightJob(serverId)) {
104	    return { error: "Another operation is already in progress on this server." };
105	  }
106	
107	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
108	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
109	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
110	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
111	  // customer must delete it (which cleanly destroys just that disk) first.
112	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
113	  if (pinnedVolumes > 0) {
114	    return {
115	      error: `Delete the ${pinnedVolumes} block-storage volume${pinnedVolumes === 1 ? "" : "s"} on this server before reinstalling — a reinstall wipes the whole disk, and volume data can't be recovered.`,
116	    };
117	  }
118	
119	  // Persist the target OS first so the REINSTALL handler (which re-provisions
120	  // from Server.osTemplateId) rebuilds onto the new image, then enqueue.
121	  await db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } });
122	  await db.job.create({ data: { type: "REINSTALL", serverId } });
123	  await db.auditLog.create({
124	    data: {
125	      userId: user.id,
126	      action: "server.reinstall_os",
127	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
128	    },
129	  });
130	  revalidatePath(`/dashboard/servers/${serverId}`);
131	  return {};
132	}
133	
134	// ---------- 3. Resize-down ----------
135	
136	/**
137	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
138	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
139	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
140	 * otherwise). A prorated credit for the price difference over the remaining term
141	 * is returned to the wallet.
142	 */
143	export async function resizeServerDown(
144	  serverId: string,
145	  newPlanId: string
146	): Promise<{ error?: string }> {
147	  const { user, server } = await ownedServer(serverId);
148	
149	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
150	  if (!newPlan?.active) return { error: "Plan not available." };
151	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
152	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
153	
154	  // This action is downgrades only — upgrades go through resizeServer().
155	  if (newPlan.priceCents >= server.plan.priceCents) {
156	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
157	  }
158	  // Disk can't shrink destructively; block the move rather than lose data.
159	  if (newPlan.diskGB < server.plan.diskGB) {
160	    return {
161	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
162	    };
163	  }
164	
165	  if (await hasInflightJob(serverId)) {
166	    return { error: "Another operation is already in progress on this server." };
167	  }
168	
169	  // Prorated credit over the ACTUAL remaining duration, not a fraction of a single
170	  // term. `renewNow` can stack expiresAt many terms into the future, so the old
171	  // "fraction of one term" clamp under-credited (or over-credited) prepaid users.
172	  // Credit the monthly price difference for every remaining month. Null expiresAt
173	  // (free/admin servers) => 0.
174	  let creditCents = 0;
175	  if (!server.isFree && server.expiresAt) {
176	    const now = Date.now();
177	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
178	    const monthlyDelta = server.plan.priceCents - newPlan.priceCents; // positive: old monthly > new monthly
179	    creditCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
180	  }
181	
182	  await db.$transaction([
183	    ...(creditCents > 0
184	      ? [
185	          db.user.update({
186	            where: { id: server.userId },
187	            data: { balanceCents: { increment: creditCents } },
188	          }),
189	          db.walletTransaction.create({
190	            data: {
191	              userId: server.userId,
192	              amountCents: creditCents,
193	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
194	            },
195	          }),
196	        ]
197	      : []),
198	    // Record the amount credited on the job so the worker's RESIZE handler can
199	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
200	    // terminally fails — the credit is committed here, before the job runs.
201	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
202	    db.job.create({
203	      data: {
204	        type: "RESIZE",
205	        serverId,
206	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
207	      },
208	    }),
209	    db.auditLog.create({
210	      data: {
211	        userId: user.id,
212	        action: "server.resize_down",
213	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
214	      },
215	    }),
216	  ]);
217	
218	  revalidatePath(`/dashboard/servers/${serverId}`);
219	  return {};
220	}
221

1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { requireArea } from "./rbac";
9	import { debitWallet, InsufficientBalanceError } from "./wallet";
10	import { capacityCheck } from "./capacity";
11	import { addMonths } from "./billing-terms";
12	import { GAME_FAMILIES, type GameFamily } from "./games";
13	import { getSettingBool, getSettingInt } from "./settings";
14	
15	/**
16	 * Game servers as a distinct product. A `GamePlan` is one pricing tier for one
17	 * game (Minecraft 2 GB / 10 slots, etc). Admins (billing area) manage the
18	 * catalogue; customers order a tier, which provisions a VM sized by the tier's
19	 * base VPS Plan running the game's OsTemplate image.
20	 *
21	 * This module owns:
22	 *   - adminSaveGamePlan / adminToggleGamePlan / adminDeleteGamePlan (CRUD)
23	 *   - orderGameServer (customer deploy) — mirrors lib/actions.ts orderServer.
24	 */
25	
26	type Result = { error?: string; ok?: boolean };
27	
28	// ---------- Admin CRUD ----------
29	
30	const planSchema = z.object({
31	  id: z.string().optional(),
32	  gameFamily: z.enum(GAME_FAMILIES),
33	  name: z.string().min(2).max(80),
34	  ramMB: z.coerce.number().int().min(256).max(262144),
35	  cpuCores: z.coerce.number().int().min(1).max(64),
36	  diskGB: z.coerce.number().int().min(1).max(4096),
37	  slots: z.coerce.number().int().min(1).max(100000).optional(),
38	  priceCents: z.coerce.number().int().min(0).max(100000000),
39	  termMonths: z.coerce.number().int().min(1).max(36),
40	  basePlanId: z.string().min(1),
41	  osTemplateId: z.string().optional(),
42	  sortOrder: z.coerce.number().int().min(0).max(100000),
43	});
44	
45	/**
46	 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
47	 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
48	 * to the same game family, if provided).
49	 */
50	export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
51	  const admin = await requireArea("billing");
52	
53	  const rawSlots = String(formData.get("slots") ?? "").trim();
54	  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
55	  const parsed = planSchema.safeParse({
56	    id: formData.get("id") || undefined,
57	    gameFamily: formData.get("gameFamily"),
58	    name: formData.get("name"),
59	    ramMB: formData.get("ramMB"),
60	    cpuCores: formData.get("cpuCores"),
61	    diskGB: formData.get("diskGB"),
62	    slots: rawSlots === "" ? undefined : rawSlots,
63	    priceCents: formData.get("priceCents"),
64	    termMonths: formData.get("termMonths"),
65	    basePlanId: formData.get("basePlanId"),
66	    osTemplateId: rawOs === "" ? undefined : rawOs,
67	    sortOrder: formData.get("sortOrder") ?? 0,
68	  });
69	  if (!parsed.success) {
70	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
71	  }
72	  const d = parsed.data;
73	
74	  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
75	  if (!base) return { error: "Choose a valid base VPS plan for provisioning." };
76	
77	  let osTemplateId: string | null = null;
78	  if (d.osTemplateId) {
79	    const os = await db.osTemplate.findUnique({ where: { id: d.osTemplateId } });
80	    if (!os) return { error: "Selected game image not found." };
81	    if (os.family !== d.gameFamily) {
82	      return { error: `That image belongs to "${os.family}", not "${d.gameFamily}".` };
83	    }
84	    osTemplateId = os.id;
85	  }
86	
87	  const featured = formData.get("featured") === "on";
88	  const active = formData.get("active") === "on";
89	
90	  const data = {
91	    gameFamily: d.gameFamily,
92	    name: d.name.trim(),
93	    ramMB: d.ramMB,
94	    cpuCores: d.cpuCores,
95	    diskGB: d.diskGB,
96	    slots: d.slots ?? null,
97	    priceCents: d.priceCents,
98	    termMonths: d.termMonths,
99	    basePlanId: d.basePlanId,
100	    osTemplateId,
101	    featured,
102	    active,
103	    sortOrder: d.sortOrder,
104	  };
105	
106	  if (d.id) {
107	    const existing = await db.gamePlan.findUnique({ where: { id: d.id } });
108	    if (!existing) return { error: "Tier not found." };
109	    await db.gamePlan.update({ where: { id: d.id }, data });
110	  } else {
111	    await db.gamePlan.create({ data });
112	  }
113	
114	  await db.auditLog.create({
115	    data: {
116	      userId: admin.id,
117	      action: d.id ? "gameplan.update" : "gameplan.create",
118	      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
119	    },
120	  });
121	  revalidatePath("/admin/game-plans");
122	  return { ok: true };
123	}
124	
125	/** Flip a tier's active flag. */
126	export async function adminToggleGamePlan(id: string): Promise<void> {
127	  const admin = await requireArea("billing");
128	  const gp = await db.gamePlan.findUnique({ where: { id } });
129	  if (!gp) return;
130	  await db.gamePlan.update({ where: { id }, data: { active: !gp.active } });
131	  await db.auditLog.create({
132	    data: { userId: admin.id, action: "gameplan.toggle", detail: `${gp.name} → active=${!gp.active}` },
133	  });
134	  revalidatePath("/admin/game-plans");
135	}
136	
137	/** Delete a tier. Refused while servers reference it. */
138	export async function adminDeleteGamePlan(id: string): Promise<Result> {
139	  const admin = await requireArea("billing");
140	  const gp = await db.gamePlan.findUnique({
141	    where: { id },
142	    include: { _count: { select: { servers: true } } },
143	  });
144	  if (!gp) return { error: "Tier not found." };
145	  if (gp._count.servers > 0) {
146	    return { error: `Can't delete — ${gp._count.servers} server(s) use this tier. Disable it instead.` };
147	  }
148	  await db.gamePlan.delete({ where: { id } });
149	  await db.auditLog.create({
150	    data: { userId: admin.id, action: "gameplan.delete", detail: `${gp.gameFamily} — ${gp.name}` },
151	  });
152	  revalidatePath("/admin/game-plans");
153	  return { ok: true };
154	}
155	
156	// ---------- Customer deploy ----------
157	
158	/** Short random suffix so auto-generated hostnames don't collide. */
159	function rand(n = 6): string {
160	  return Math.random().toString(36).slice(2, 2 + n);
161	}
162	
163	/**
164	 * Order a game server from a GamePlan tier. Mirrors lib/actions.ts orderServer:
165	 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
166	 * create the Server (sized by the tier's base VPS plan, running the game image)
167	 * plus a PROVISION Job in one transaction. Redirects to the new server.
168	 */
169	export async function orderGameServer(gamePlanId: string): Promise<Result> {
170	  const user = await requireUser();
171	
172	  // Feature flag: game servers can be switched off platform-wide.
173	  if (!(await getSettingBool("feature_game_servers", true))) {
174	    return { error: "Game servers aren't available right now." };
175	  }
176	
177	  // Game servers are Server rows too, so they count toward the per-user cap
178	  // (`max_servers_per_user`, default 10; 0 = unlimited).
179	  const cap = await getSettingInt("max_servers_per_user", 10);
180	  if (cap > 0) {
181	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
182	    if (owned >= cap) {
183	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
184	    }
185	  }
186	
187	  const gp = await db.gamePlan.findUnique({
188	    where: { id: gamePlanId },
189	    include: { basePlan: true },
190	  });
191	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
192	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
193	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
194	    return { error: "Unknown game family." };
195	  }
196	
197	  // Resolve the game image: the tier's own OsTemplate, else any active image for
198	  // this game family. A game server can't provision without an image.
199	  let osTemplateId = gp.osTemplateId;
200	  if (osTemplateId) {
201	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
202	    if (!os?.active) osTemplateId = null;
203	  }
204	  if (!osTemplateId) {
205	    const os = await db.osTemplate.findFirst({
206	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
207	      orderBy: { sortOrder: "asc" },
208	    });
209	    if (!os) return { error: "No game image is configured for this game yet." };
210	    osTemplateId = os.id;
211	  }
212	
213	  const chargeCents = gp.priceCents;
214	  if (user.balanceCents < chargeCents) {
215	    return { error: "Insufficient balance. Top up your wallet first." };
216	  }
217	
218	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
219	  // letting game servers commit host RAM past capacity. Check the base plan's
220	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
221	  const capacity = await capacityCheck(gp.basePlanId);
222	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
223	
224	  const hostname = `${gp.gameFamily}-${rand()}`;
225	
226	  let server;
227	  try {
228	    server = await db.$transaction(async (tx) => {
229	      await debitWallet(tx, user.id, chargeCents);
230	      await tx.walletTransaction.create({
231	        data: {
232	          userId: user.id,
233	          amountCents: -chargeCents,
234	          description: `Game server: ${gp.name} (${gp.gameFamily})`,
235	        },
236	      });
237	      const s = await tx.server.create({
238	        data: {
239	          name: hostname,
240	          hostname,
241	          userId: user.id,
242	          planId: gp.basePlanId,
243	          gamePlanId: gp.id,
244	          osTemplateId: osTemplateId!,
245	          termMonths: gp.termMonths,
246	          wantsDedicatedIp: false,
247	          expiresAt: addMonths(new Date(), gp.termMonths),
248	        },
249	      });
250	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
251	      return s;
252	    });
253	  } catch (e) {
254	    if (e instanceof InsufficientBalanceError) {
255	      return { error: "Insufficient balance. Top up your wallet first." };
256	    }
257	    throw e;
258	  }
259	
260	  await db.auditLog.create({
261	    data: {
262	      userId: user.id,
263	      action: "gameserver.order",
264	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
265	    },
266	  });
267	  redirect(`/dashboard/servers/${server.id}`);
268	}
