165	export function fmtBytes(b: number): string {
166	  if (!b || b <= 0) return "0 B";
167	  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
168	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
169	  return `${(b / 1024 ** i).toFixed(1)} ${units[i]}`;
170	}
