export const GAME_CONFIG_SCHEMAS: Record<string, FamilySchema> = {
  minecraft: MINECRAFT,
  rust: RUST,
  valheim: VALHEIM,
  cs2: CS2,
  palworld: PALWORLD,
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Minimal shape we need off a Server row to resolve its game family. */
type ServerLike = {
  osTemplate?: { family?: string | null } | null;
  gamePlan?: { gameFamily?: string | null } | null;
};

/**
 * Resolve the game family for a server, preferring the game plan's family and
 * falling back to the OS template's family. Returns the family string ONLY if a
 * customization schema exists for it, else null.
 */
export function familyFor(server: ServerLike | null | undefined): string | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam && GAME_CONFIG_SCHEMAS[fam]) return fam;
  return null;
}

/** The customization schema for a family, or null. */
export function schemaFor(family: string | null | undefined): FamilySchema | null {
  if (!family) return null;
  return GAME_CONFIG_SCHEMAS[family] ?? null;
}

/** True if `variant` is a valid variant id for `family`. */
export function isValidVariant(family: string, variant: string): boolean {
  const s = GAME_CONFIG_SCHEMAS[family];
  return !!s && s.variants.some((v) => v.id === variant);
}

export type ValidateResult =
  | { ok: true; values: Record<string, string | number | boolean> }
  | { ok: false; error: string };

/**
 * Validate & coerce a settings object against a family's field schema. Unknown
 * keys are dropped; missing keys fall back to the field default. Returns a clean,
 * fully-populated values object ready to persist to `Server.gameConfig`.
 */
export function validateConfig(
  family: string,
  values: Record<string, unknown> | null | undefined
): ValidateResult {
  const schema = GAME_CONFIG_SCHEMAS[family];
  if (!schema) return { ok: false, error: `Unknown game family "${family}".` };

  const input = values ?? {};
  const out: Record<string, string | number | boolean> = {};

  for (const field of schema.fields) {
    const raw = input[field.key];
    const provided = raw !== undefined && raw !== null;

    switch (field.type) {
      case "bool": {
        out[field.key] = provided ? raw === true || raw === "true" || raw === "on" : (field.default as boolean);
        break;
      }
      case "int": {
        let n = provided ? Number(raw) : (field.default as number);
        if (!Number.isFinite(n)) return { ok: false, error: `${field.label} must be a number.` };
        n = Math.trunc(n);
        if (field.min !== undefined && n < field.min)
          return { ok: false, error: `${field.label} must be at least ${field.min}.` };
        if (field.max !== undefined && n > field.max)
          return { ok: false, error: `${field.label} must be at most ${field.max}.` };
        out[field.key] = n;
        break;
      }
      case "enum": {
        const v = provided ? String(raw) : String(field.default);
        if (!field.options?.some((o) => o.value === v))
          return { ok: false, error: `Invalid value for ${field.label}.` };
        out[field.key] = v;
        break;
      }
      case "string": {
        const v = provided ? String(raw) : String(field.default);
        if (v.length > 256) return { ok: false, error: `${field.label} is too long (max 256 chars).` };
        out[field.key] = v;
        break;
      }
    }
  }

  return { ok: true, values: out };
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import {
  familyFor,
  schemaFor,
  isValidVariant,
  validateConfig,
  type FamilySchema,
} from "./game-config";

/**
 * Per-game customization actions (MVP).
 *
 * Customers pick a server *variant* (loader/flavour) and tune a small set of
 * game settings from the portal. Saving validates against the family schema
 * (lib/game-config.ts), persists `Server.gameVariant` + `Server.gameConfig`, and
 * enqueues a GAME_CONFIG job that the worker applies (simulated in MVP).
 *
 * Ownership + the "one in-flight job per server" invariant mirror
 * lib/actions-server-lifecycle.ts.
 */

/** Owner (or admin) resolution — includes the relations `familyFor` needs. */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

export type GameConfigView = {
  family: string;
  schema: FamilySchema;
  variant: string;
  values: Record<string, string | number | boolean>;
};

/**
 * Load the current customization state for an owned game server: the resolved
 * family + its schema, the selected variant (defaulting to the schema default)
 * and the stored settings values (validated/normalised against the schema so the
 * UI always gets a complete, well-typed object).
 */
export async function getGameConfig(
  serverId: string
): Promise<{ error?: string; config?: GameConfigView }> {
  const { server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  const variant =
    server.gameVariant && isValidVariant(family, server.gameVariant)
      ? server.gameVariant
      : schema.defaultVariant;

  const validated = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
  const values = validated.ok ? validated.values : {};

  return { config: { family, schema, variant, values } };
}

/**
 * Validate and persist a server's game variant + settings, then enqueue a
 * GAME_CONFIG job to apply them. Refuses while another job is in flight.
 */
export async function saveGameConfig(
  serverId: string,
  variant: string,
  values: Record<string, unknown>
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  if (!isValidVariant(family, variant)) {
    return { error: "Pick a valid server type for this game." };
  }

  const validated = validateConfig(family, values);
  if (!validated.ok) return { error: validated.error };

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.server.update({
    where: { id: server.id },
    data: { gameVariant: variant, gameConfig: validated.values as any },
  });
  await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.config",
      detail: `${serverId} family=${family} variant=${variant}`,
    },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { familyFor, schemaFor, GAME_CONFIG_VERSION } from "../lib/game-config";
import type { Job } from "@prisma/client";

/**
 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
 *
 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
 *   GAME_CONFIG: gameConfigApply,
 *
 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
 *
 * MVP SCOPE: actually pushing settings to a live game server (rewriting
 * server.properties / PalWorldSettings.ini / running RCON cvars and restarting
 * the service over SSH) is deferred. For now this handler is a safe no-op on real
 * infra: it records an "applied" marker on `Server.gameConfig` and notifies the
 * user. This keeps the portal flow (save → job → "applied" notification) working
 * end to end without touching customer VMs.
 *
 * TODO(real apply): per family, SSH to `server.ipAddress` (sshpass + rootPassword,
 * as worker/game-update.ts does) and:
 *   - minecraft: write server.properties keys, restart the service
 *   - rust:      set convars via RCON (or startup args) + restart
 *   - valheim:   rewrite launch args / adminlist, restart
 *   - cs2:       set cvars via RCON + relaunch for -tickrate/game_mode
 *   - palworld:  write PalWorldSettings.ini, restart
 * Gate the real path behind `!SANDBOX` and keep the marker/notify below.
 */

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-config] notify failed", e);
  }
}

export async function gameConfigApply(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game config: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
  }

  const variant = server.gameVariant ?? schema.defaultVariant;

  // MVP: simulate the apply (always, and explicitly under SANDBOX). We stamp a
  // small applied-marker alongside the existing values so the portal can show the
  // last-applied variant/time, then notify the user. No SSH, no VM mutation.
  // TODO(real apply): replace this block with the per-family SSH/RCON logic above
  // when !SANDBOX and the server is RUNNING with an IP/password.
  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const marker = {
    _appliedVariant: variant,
    _appliedAt: new Date().toISOString(),
    _configVersion: GAME_CONFIG_VERSION,
    _sandbox: SANDBOX,
  };

  await db.server.update({
    where: { id: server.id },
    data: { gameConfig: { ...existing, ...marker } as any },
  });

  await notify(
    server.userId,
    `Game settings applied on ${server.hostname}`,
    `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
    `/dashboard/servers/${server.id}?tab=game settings`
  );
}

"use client";

import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { saveGameConfig } from "@/lib/actions-game-config";
import type { ConfigField, FamilySchema } from "@/lib/game-config";

type Values = Record<string, string | number | boolean>;

/**
 * Dynamic per-game settings form. Renders the family schema (grouped fields, the
 * right widget per type) plus a variant/loader picker, and persists via
 * `saveGameConfig` — which validates, stores the values and enqueues a
 * GAME_CONFIG job to apply them.
 */
export function GameSettings({
  serverId,
  schema,
  variant: initialVariant,
  values: initialValues,
  disabled,
}: {
  serverId: string;
  schema: FamilySchema;
  variant: string;
  values: Values;
  disabled?: boolean;
}) {
  const router = useRouter();
  const [variant, setVariant] = useState(initialVariant);
  const [values, setValues] = useState<Values>(initialValues);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);
  const [pending, start] = useTransition();

  // Fields grouped by their `group` heading, preserving declaration order.
  const groups = useMemo(() => {
    const map = new Map<string, ConfigField[]>();
    for (const f of schema.fields) {
      if (!map.has(f.group)) map.set(f.group, []);
      map.get(f.group)!.push(f);
    }
    return [...map.entries()];
  }, [schema]);

  function set(key: string, value: string | number | boolean) {
    setValues((v) => ({ ...v, [key]: value }));
    setSaved(false);
  }

  function save() {
    start(async () => {
      setError(null);
      setSaved(false);
      const res = await saveGameConfig(serverId, variant, values);
      if (res?.error) setError(res.error);
      else {
        setSaved(true);
        router.refresh();
      }
    });
  }

  const activeVariant = schema.variants.find((v) => v.id === variant);

  return (
    <div className="card">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h2 className="font-semibold">Game settings</h2>
          <p className="mt-1 max-w-xl text-sm text-slate-400">
            Configure your {schema.label} server. Changes are queued and applied to the server —
            some settings only take effect after the next restart.
          </p>
        </div>
        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
          {pending ? "Saving…" : "Save & apply"}
        </button>
      </div>

      {/* Variant / loader picker */}
      <div className="mt-5">
        <label className="block text-sm">
          <span className="mb-1.5 block font-medium">Server type</span>
          <select
            className="input"
            value={variant}
            disabled={pending || disabled}
            onChange={(e) => {
              setVariant(e.target.value);
              setSaved(false);
            }}
          >
            {schema.variants.map((v) => (
              <option key={v.id} value={v.id}>
                {v.label}
              </option>
            ))}
          </select>
        </label>
        {activeVariant?.description && (
          <p className="mt-1.5 text-xs text-slate-500">{activeVariant.description}</p>
        )}
      </div>

      {groups.map(([group, fields]) => (
        <div key={group} className="mt-6">
          <p className="section-label">{group}</p>
          <div className="mt-3 grid gap-4 sm:grid-cols-2">
            {fields.map((f) => (
              <Field
                key={f.key}
                field={f}
                value={values[f.key]}
                disabled={pending || disabled}
                onChange={(val) => set(f.key, val)}
              />
            ))}
          </div>
        </div>
      ))}

      <div className="mt-5 flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
          {pending ? "Saving…" : "Save & apply"}
        </button>
        {saved && !error && <span className="text-sm text-emerald-400">Settings queued for apply.</span>}
        {error && <span className="text-sm text-red-400">{error}</span>}
      </div>
    </div>
  );
}

function Field({
  field,
  value,
  disabled,
  onChange,
}: {
  field: ConfigField;
  value: string | number | boolean | undefined;
  disabled?: boolean;
  onChange: (v: string | number | boolean) => void;
}) {
  const labelRow = (
    <span className="mb-1.5 flex items-baseline justify-between gap-2">
      <span className="font-medium">{field.label}</span>
      {field.phase === "deploy" && (
        <span className="text-[10px] uppercase tracking-wide text-amber-300/80">restart</span>
      )}
    </span>
  );

  if (field.type === "bool") {
    const on = value === true;
    return (
      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
        <span className="text-sm">
          <span className="font-medium">{field.label}</span>
          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
        </span>
        <button
          type="button"
          role="switch"
          aria-checked={on}
          disabled={disabled}
          onClick={() => onChange(!on)}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            on ? "bg-brand-500" : "bg-white/15"
          } ${disabled ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              on ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      </div>
    );
  }

  return (
    <label className="block text-sm">
      {labelRow}
      {field.type === "enum" ? (
        <select
          className="input"
          value={String(value ?? field.default)}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
        >
          {field.options?.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
      ) : field.type === "int" ? (
        <input
          className="input"
          type="number"
          value={value === undefined || value === null ? Number(field.default) : Number(value)}
          min={field.min}
          max={field.max}
          step={1}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
        />
      ) : (
        <input
          className="input"
          type="text"
          value={String(value ?? field.default)}
          maxLength={256}
          disabled={disabled}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
      {field.help && field.type !== "bool" && (
        <span className="mt-1 block text-xs text-slate-500">{field.help}</span>
      )}
    </label>
  );
}

